struct Command {
  virtual void execute() = 0;
  virtual void undo() = 0;
  virtual ~Command() = default;
};

struct InsertText : Command {
  Document& doc; std::string text; std::size_t pos;
  void execute() override { doc.insert(pos, text); }
  void undo() override { doc.erase(pos, text.size()); }
};

using Edit = std::variant<InsertText, DeleteRange>;
std::vector<Edit> history;

void apply(Document& doc, const Edit& e) {
  std::visit(overloaded{
    [&](const InsertText& c) { doc.insert(c.pos, c.text); },
    [&](const DeleteRange& c) { doc.erase(c.pos, c.len); }}, e);
}
